//  The background is baked to TILE_BG_OFF (0x0C0F13) rather than
//  carried as an alpha channel - alpha would cost 50% more flash
//  and a blend on every redraw, and these only ever sit on that
//  one tile colour.
//  Cut from the product photograph supplied by Shemi.
// ============================================================
